/* LINPACK as a sliced job, included once per precision by k_lin_d.c / k_lin_f.c. Own code, CC0.
 *
 * lin_d.c / lin_f.c are the netlib linpack.c (Toy, Menninger, Dongarra), generated by gen.py: main() and linpack()
 * replaced by LN_PHASE(roll), one matgen + timed dgefa + timed dgesl on the 200 x 200 array (n = 100) the Hatari
 * build solved, and a residual: the solution of that system is all ones, so max |x - 1| says whether it solved it.
 * A slice is one phase; the phases alternate rolled and unrolled BLAS, as the original's two loops do, and
 * KFLOPS = flops of the phases / the time inside dgefa + dgesl (matgen and the residual are not timed). */
#include "bench.h"
#include "../../zigmachine_mem.h"

#define PASTE(a, b) a##b
#define CAT(a, b) PASTE(a, b)
extern void CAT(LN_, INIT)(void *mem);
extern void CAT(LN_, PHASE)(int roll);
extern REAL_T CAT(LN_, RESIDUAL)(void);
extern long CAT(LN_, T_GEFA), CAT(LN_, T_GESL);

#define FLOPS_PER_PHASE 686667ull       /* 2/3 n^3 + 2 n^2 at n = 100 */

static slicer sl;
static zm_mark mark;
static void *mem;
static double worst;

static void begin(void) {
    sl_begin(&sl, 1, 1);
    mark = zm_mark_now();
    mem = zm_alloc(200u * 200u * sizeof(REAL_T) + 200u * sizeof(REAL_T) + 200u * sizeof(int), 8);
    if (mem) CAT(LN_, INIT)(mem);
    CAT(LN_, T_GEFA) = CAT(LN_, T_GESL) = 0;
    worst = 0;
}

static int step(void) {
    if (!mem) return 0;
    long before = CAT(LN_, T_GEFA) + CAT(LN_, T_GESL);
    CAT(LN_, PHASE)((int)(sl.slices & 1) == 0);
    double r = (double)CAT(LN_, RESIDUAL)();
    if (!(r == r) || r > worst) worst = r == r ? r : 1e30;
    sl_note(&sl, (u32)(CAT(LN_, T_GEFA) + CAT(LN_, T_GESL) - before));
    return sl_more(&sl);
}

static void finish(bench_res *r) {
    res_clear(r);
    res_check(r, mem != 0 && worst < RESID_LIMIT, !mem ? "OUT OF MEMORY" : (worst < RESID_LIMIT ? "solution = 1, residual small" : "RESIDUAL TOO LARGE"));
    if (sl.clocked && sl.us) res_val(r, NAME, "KFLOPS", sl.work * FLOPS_PER_PHASE * 1000000ull / sl.us);
    res_val(r, NAME "_resid", "x 1e-9", (u64)(worst * 1e12));
    zm_release(mark);
}

const bench_job JOB = { NAME, LABEL, begin, step, finish };
